import{_ as i,l,o as e,c as o,v as t,p as d,x as r,d as s,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"延迟奖励与信用分配","description":"","frontmatter":{"title":"延迟奖励与信用分配","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/delayed-reward-trading.md","filePath":"quant/delayed-reward-trading.md","lastUpdated":1789023840000}'),E={name:"quant/delayed-reward-trading.md"};function m(u,a,c,A,B,_){const n=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="延迟奖励与信用分配" tabindex="-1">延迟奖励与信用分配 <a class="header-anchor" href="#延迟奖励与信用分配" aria-label="Permalink to &quot;延迟奖励与信用分配&quot;">​</a></h1><div class="epigraph"><p>强化学习里的奖励若在动作当时不可观测，信用必须沿时间回传。交易的盈亏往往在持有期结束、成交完全填完或隔夜之后才清楚，逐步标记收益会把噪声当成即时强化。</p><footer>—— 据 Sutton and Barto 对 delayed reward 与 credit assignment 的论述；对照执行问题里实施缺口在订单生命周期结束才结算</footer></div><p><a href="/quant/rl-execution">执行 RL 与冲击</a>把奖励写成负的实施缺口加库存风险，并警告模拟器偏差。<a href="/quant/trading-mdp-pitfalls">交易作为 MDP</a>已经指出奖励延迟致命。本课的缺口是专门处理<strong>延迟奖励</strong>：当 \\(R\\) 不能在每个微观动作上诚实给出时，如何定义回合、如何分配信用、以及错误分配如何把冲击学成方向赌博。后课部分可观测成交与模拟器冲击，都默认奖励时钟已经选对。不重写 Almgren–Chriss 轨迹。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>做市或执行的动作是毫秒级的挂撤，经济结果是：若干秒后的填成、若干分钟后的中点移动、日终的 PnL、T+1 才可卖。若每步用中间价盯市当 \\(R_t\\)，等于把未实现估值当强化，智能体会为了瞬时标记去招手感盘，而不是为了可实现缺口。若只在回合结束给一个 \\(R_T\\)，信用要沿成百上千步反传，样本效率极差，且中间的风控动作（暂停、降仓）难以被学习。缺口是显式选择奖励时钟，使其与策略<a href="/quant/holding-horizon">持有期</a>同阶，而不是同阶于神经网络的步长。</p><p>信用分配的错误模式：把随后因公开新闻导致的价跳归功于某次挂单；把因自己冲击造成的不利移动归咎于「随机」。前者过拟合公告，后者学不会永久冲击。</p><h3 id="回合如何切" tabindex="-1">回合如何切 <a class="header-anchor" href="#回合如何切" aria-label="Permalink to &quot;回合如何切&quot;">​</a></h3><p>执行任务天然有回合：\\(Q\\) 在 \\(T\\) 内完成或放弃。方向性交易的回合更含糊。应按产品切：一次再平衡、一个交易日、一次拍卖。跨日且 T+1 时，买入动作的奖励不得在当日卖出权还不存在时结算「完成」。混频体制（信号日频、执行高频）应分层奖励：执行层只对缺口负责，信号层只对持有期收益负责，禁止一个网络吃两层。</p><p><span class="marginnote">折扣 \\(\\gamma\\) 不能代替回合定义。把 \\(\\gamma\\) 调到 0.99 去「让智能体看得远」，只是把未声明的 \\(H\\) 藏进超参。先修 MDP 课已经警告过。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写可审计的即时分量：手续费、已实现缺口、明确的库存惩罚（与 Almgren 风险项对齐）。延迟分量：填成结束后的实现价差（选与 \\(H\\) 匹配的 \\(\\tau\\)）、未完成量的机会成本。用资格迹或 n-step 回报把延迟分量赋给导致该填成的动作序列，而不是赋给时间上最近的一个动作——最近动作常常只是偶然的最后一撤。</p><p>对照实验：同一政策，用逐步盯市训练 vs 用回合缺口训练，看实盘填成与缺口。若逐步盯市在模拟器里夏普更高、实盘更差，几乎一定是标记噪声。Nevmyvaka 等的执行 RL 实验对象是短地平线执行，奖励与任务对齐；把同一套用到隔夜方向，任务已经换了。</p><h3 id="稀疏奖励与塑造" tabindex="-1">稀疏奖励与塑造 <a class="header-anchor" href="#稀疏奖励与塑造" aria-label="Permalink to &quot;稀疏奖励与塑造&quot;">​</a></h3><p>纯回合奖励稀疏。允许塑造（potential-based shaping）时，势能必须是状态的函数且不引入动态套利：例如剩余量下降给小奖励，但不得对中点朝有利方向移动给奖励——那是在奖励市场噪声。Gatheral 的无动态套利要求出现在奖励里：不能通过来回成交从自己的永久冲击领钱。违反时，延迟奖励会被智能体「提前实现」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>延迟使归因矩阵病态：许多动作共享一个结果。市场非平稳又使同一动作的结果分布漂移。于是智能体把在样本里碰巧先于盈利的微观模式当成政策。这与回测过拟合同构，只是优化器换成了 RL。把奖励时钟对齐 \\(H\\)，等于减少需要归因的步数，病态减轻。把执行与方向分开，等于不让执行网络去抢本属于信号的延迟收益。</p><p><span class="marginnote">实现价差曲线提供了一种延迟度量：\\(\\mathrm{RS}(\\tau)\\) 正是「转手之后还剩多少」。执行 RL 的延迟分量应读这条曲线的 \\(\\tau\\)，而不是读一个任意的 bootstrap 步数。</span></p>',17)),(e(),d(h,null,{default:r(()=>[p(n,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%BE%AE%E8%A7%82%E5%8A%A8%E4%BD%9C%22%5D%20--%3E%20F%5B%22%E5%A1%AB%E6%88%90%E4%B8%8E%E8%B4%B9%E7%94%A8%EF%BC%9A%E5%8F%AF%E5%8D%B3%E6%97%B6%22%5D%0A%20%20A%20--%3E%20D%5B%22H%20%E5%90%8E%E7%9A%84%20PnL%20%2F%20%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%EF%BC%9A%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20D%20--%3E%20C%5B%22%E4%BF%A1%E7%94%A8%E5%88%86%E9%85%8D%E5%88%B0%E5%8A%A8%E4%BD%9C%E5%BA%8F%E5%88%97%22%5D%0A%20%20F%20--%3E%20R%5B%22%E5%A5%96%E5%8A%B1%20R%22%5D%0A%20%20C%20--%3E%20R%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="资格迹应对准导致填成的动作序列" tabindex="-1">资格迹应对准导致填成的动作序列 <a class="header-anchor" href="#资格迹应对准导致填成的动作序列" aria-label="Permalink to &quot;资格迹应对准导致填成的动作序列&quot;">​</a></h3><p>把延迟缺口赋给时间上最后一次撤单，会训练出无意义的结束动作。信用应沿仍挂着的订单链回传。订单状态机是归因的骨架，不是装饰。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>组合层 RL（直接优化夏普）把延迟拉到整段回测，信用分配几乎不可能诚实，过拟合课已覆盖。本课对象是执行与做市这类短回合。下一课：即使奖励时钟对了，你也看不见填成与队列的真状态。</p><p><span class="marginnote">组合层直接优化夏普，延迟拉到整段回测，信用分配几乎不可识别。那是过拟合课的对象，不要当成本课的 RL 成功。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>奖励时钟必须与持有期同阶，不能与神经网络步长同阶。</li><li>逐步盯市把噪声当强化；纯终局奖励使归因病态。</li><li>执行与方向分层，禁止一个网络领取两层延迟收益。</li><li>塑造不得奖励中点的随机有利移动，也不得创造冲击套利。</li><li>实现价差的 \\(\\tau\\) 是执行延迟分量的自然尺度。</li><li>出处：Sutton and Barto, <em>Reinforcement Learning</em>；Nevmyvaka, Feng and Kearns, 2006；Almgren and Chriss；Gatheral 对冲击无动态套利；实现价差见 Huang–Stoll 会计。</li></ul>',7))])}const q=i(E,[["render",m]]);export{g as __pageData,q as default};
